`PREC = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
def to_postfix(expr):
    out, st = [], []
    for t in expr.split():
        if t.isalnum():
            out.append(t)
        elif t == '(':
            st.append(t)
        elif t == ')':
            while st[-1] != '(':
                out.append(st.pop())
            st.pop()
        else:
            while st and st[-1] != '(' and (PREC[st[-1]] > PREC[t] or (PREC[st[-1]] == PREC[t] and t != '^')):
                out.append(st.pop())
            st.append(t)
