def eval_postfix(tokens):
    st = []
    for t in tokens.split():
        if t.lstrip('-').isdigit():
            st.append(int(t))
        else:
            b, a = st.pop(), st.pop()
            st.append({'+': a + b, '-': a - b, '*': a * b, '/': a // b}[t])
    return st[0]
