`import heapq
def frac_knap(items, W):
    total = 0
    for v, w in sorted(items, key=lambda x: x[0] / x[1], reverse=True):
        take = min(w, W)
        total += v * take / w
        W -= take
    return total
def job_seq(jobs):
    slots = [None] * (max(d for _, d in jobs) + 1)
    for p, d in sorted(jobs, reverse=True):
        for t in range(d, 0, -1):
            if slots[t] is None:
                slots[t] = p
                break
    return sum(x for x in slots if x)
def merge_cost(sizes):
    h = list(sizes); heapq.heapify(h); cost = 0
    while len(h) > 1:
        a, b = heapq.heappop(h), heapq.heappop(h)
        cost += a + b; heapq.heappush(h, a + b)
    return cost
def activities(acts):
    end, n = -1, 0
    for s, f in sorted(acts, key=lambda x: x[1]):
        if s >= end: n += 1; end = f
    return n
