`def crc_remainder(msg, gen):
    bits = list(msg + "0" * (len(gen) - 1))
    for i in range(len(msg)):
        if bits[i] == "1":
            for j, g in enumerate(gen):
                bits[i + j] = str(int(bits[i + j]) ^ int(g))
    return "".join(bits[-(len(gen) - 1):])

def tcp_cwnd(rounds, ssthresh, timeout_at=None):
    cwnd, trace = 1, []
    for r in range(rounds):
        trace.append(cwnd)
        if r == timeout_at:
            ssthresh, cwnd = max(cwnd // 2, 2), 1
        elif cwnd < ssthresh:
            cwnd = min(2 * cwnd, ssthresh)
        else:
            cwnd += 1
    return trace

