`def fragment(total_len, hdr, mtu):
    data, maxd, off, out = total_len - hdr, (mtu - hdr) // 8 * 8, 0, []
    while data > 0:
        d = min(maxd, data); data -= d
        out.append({'len': d + hdr, 'data': d, 'offset': off // 8, 'MF': int(data > 0)})
        off += d
    return out
